import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {A,assets,c,root,createCanvas,ImageData} from './load-assets.mjs';import {createJangmokEnvironment} from '../environment.mjs';import {renderNativeHome} from '../render.mjs';
