const reference=new Function('ctx','A','S','ImageData','F',`const{M,contract,source,indices,rgb,actors,actorData,signs,depthAssets,b2Contract,b2Atlas,b4Payload,b1Payload,b3Contract,b3Atlas,screen,ambient,rc,rz,safeData}=A;const{sharedPhase,applyDerivedWater,applyB1,B1REV,applyB4,B4REV,selectB2,selectB3,sampleNightMix}=F;const{foot,pose,camera,worldMs,minutes}=S;const clockOwner={read:()=>({absoluteMinutes:minutes})},previewSchedule={dawnStart:300,dayStart:420,duskStart:1080,nightStart:1200},lightingFrame=new Uint8ClampedArray(960*540*4),actorMask=new Uint8Array(960*540);let nightMix=0,dirty=true,lastPhase=-1;const regionsVerified=true,b1Verified=true,b2AssetsVerified=true,b3Verified=true,b4Verified=true,b1On=true,b2On=true,b3On=true,b4On=true,b1Bad=false,b3Bad=false,b4Bad=false,b1LoadError=null,b2LoadError=null,b3LoadError=null,b4LoadError=null,b2GuardMode='VALID',guard=true,sceneIndex=0,walking=false,walkIndex=0,paused=false,waterOn=true,sortOn=true,depthOn=true,$=()=>({textContent:''}),window={};const supported=(x,y)=>safeData[(y*5120+x)*4]>0;${d}\n${l}\n${r}\nrender();return window.__combinedQA;`),F={sharedPhase,applyDerivedWater,applyB1,B1REV,applyB4,B4REV,selectB2,selectB3,sampleNightMix};
test('selected Jangmok R3 actorOFF24frames and actorON24frames pixel exact: both homes+both boat cameras day/night phases',()=>{let count=0;const a=createCanvas(960,540),b=createCanvas(960,540),empty=createCanvas(107,107);for(const actorEnabled of [false,true])for(const foot of [[3280,535],[452,1215],[600,400],[4000,400]])for(const minutes of [720,1320])for(const worldMs of [0,550,4750]){const env=createJangmokEnvironment(A);env.tick(worldMs);env.setTime(minutes);b.width=960;b.height=540;const info=renderNativeHome(a.getContext('2d'),{contract:c,assets,environment:env,status:{scene:'exterior',foot,facing:'up'},actorEnabled}),refA=actorEnabled?A:{...A,actors:A.actors.map(()=>empty),actorData:A.zeroActorData};reference(b.getContext('2d'),refA,{foot,pose:9,camera:info.camera,worldMs,minutes},ImageData,F);const aa=a.getContext('2d').getImageData(0,0,960,540).data,bb=b.getContext('2d').getImageData(0,0,960,540).data;const first=aa.findIndex((v,i)=>v!==bb[i]);assert.equal(first,-1,JSON.stringify({actorEnabled,foot,minutes,worldMs,first,actual:aa[first],expected:bb[first]}));count++;globalThis.gc?.()}assert.equal(count,48)});
test('actor day/mid/night alpha outside identical and opaque ambient once for both homes/fourstaticposes',()=>{let checks=0,changed=0;const on=createCanvas(960,540),off=createCanvas(960,540),ambient=createFrameLighting({nightTint:A.LM.ambientTint});for(const homeId of ['upper','family'])for(const facing of ['down','right','left','up'])for(const minutes of [720,1140,1320]){const env=createJangmokEnvironment(A);env.setTime(minutes);const s={scene:'exterior',foot:c.houses[homeId].exteriorDoor.readFoot,facing},r=renderNativeHome(on.getContext('2d'),{contract:c,assets,environment:env,status:s});renderNativeHome(off.getContext('2d'),{contract:c,assets,environment:env,status:s,actorEnabled:false});const a=on.getContext('2d').getImageData(0,0,960,540).data,b=off.getContext('2d').getImageData(0,0,960,540).data,raw=A.actorData[r.pose],expected=raw.slice();ambient(raw,expected,env.read().nightMix);const x=s.foot[0]-r.camera[0]-53,y=s.foot[1]-r.camera[1]-90;for(let py=0;py<540;py++)for(let px=0;px<960;px++){const k=(py*960+px)*4,inside=px>=x&&px<x+107&&py>=y&&py<y+107,j=((py-y)*107+px-x)*4,alpha=inside?raw[j+3]:0;if(alpha===0){for(let ch=0;ch<4;ch++)assert.equal(a[k+ch],b[k+ch])}else if(alpha===255){for(let ch=0;ch<3;ch++){assert.equal(a[k+ch],expected[j+ch]);if(a[k+ch]!==raw[j+ch])changed++}}}checks++;globalThis.gc?.()}assert.equal(checks,24);assert(changed>0)});
test('single original clock, options, pause and hidden baseline retain elapsed without scene coupling',()=>{const e=createJangmokEnvironment(A);e.setOption('b2',false);e.setOption('water',false);e.setOption('lights',false);e.setTime(1320);assert.equal(e.tickRAF(1000),0);e.tickRAF(1050);const before=e.read();e.tickRAF(2050,false);assert.equal(e.read().elapsedMs,before.elapsedMs);e.setOption('paused',true);e.tickRAF(2100);assert.equal(e.read().elapsedMs,before.elapsedMs);e.setOption('paused',false);e.tickRAF(2150);assert.equal(e.read().elapsedMs,100);assert.equal(e.read().clockOwnerCount,1);assert.equal(e.read().options.b2,false);assert.equal(e.read().options.water,false);assert.equal(e.read().options.lights,false);assert.throws(()=>e.tickRAF(2000),/Non-monotonic/)});
test('demo rate changes lighting only; scrub never resets boat/water elapsed',()=>{const e=createJangmokEnvironment(A);e.setOption('demo',true);e.tick(1000);assert.equal(e.read().elapsedMs,1000);assert.equal(e.read().absoluteMinutes,770);e.setTime(1320);assert.equal(e.read().elapsedMs,1000);e.setOption('demo',false);e.tick(60000);assert.equal(e.read().absoluteMinutes,1321)});
test('inside selected art remains unchanged while exterior clock and flags persist',()=>{const e=createJangmokEnvironment(A);e.setTime(1320);e.setOption('b4',false);for(const scene of ['upper_1F','upper_2F','family_1F']){e.tick(100);const out=createCanvas(696,464),ref=createCanvas(696,464),r=renderNativeHome(out.getContext('2d'),{contract:c,assets,environment:e,status:{scene,foot:[350,300],facing:'down'},actorEnabled:false});ref.getContext('2d').drawImage(assets[scene],0,0);assert.deepEqual(out.getContext('2d').getImageData(0,0,696,464).data,ref.getContext('2d').getImageData(0,0,696,464).data);assert.equal(r.environmentConnected,false);assert.equal(r.environment.options.b4,false)}assert.equal(e.read().elapsedMs,300)});

test('suspended RAF gap resumes with firstdelta0 and preserves water/boat phase; clock owner never replaced',()=>{const e=createJangmokEnvironment(A);e.tickRAF(1000);e.tickRAF(1050);const old=e.read();e.resetFrameBaseline();assert.equal(e.tickRAF(90000),0);assert.equal(e.read().elapsedMs,old.elapsedMs);e.tickRAF(90050);assert.equal(e.read().elapsedMs,old.elapsedMs+50);assert.equal(e.read().clockOwnerCount,1);e.tickRAF(90100,false);assert.equal(e.tickRAF(180000,true),0);assert.equal(e.read().elapsedMs,old.elapsedMs+50)});
test('both actual session roundtrips and upper twofloor transitions preserve one environment/options',async()=>{const {NativeHomeSession}=await import('../session.mjs'),masks=Object.fromEntries(Object.entries(c.masks).map(([k,s])=>[k,new Uint8Array(fs.readFileSync(new URL(s.path,root)))])),e=createJangmokEnvironment(A);e.setTime(1320);for(const k of ['water','b2','b4','lights'])e.setOption(k,false);let elapsed=0;const tick=n=>{e.tick(n);elapsed+=n},walk=(s,path)=>{for(const p of path.slice(1)){const[x,y]=s.foot;assert.equal(s.move(p[0]<x?'left':p[0]>x?'right':p[1]<y?'up':'down').ok,true)}};for(const id of ['upper','family']){const s=new NativeHomeSession({contract:c,homeId:id,masks});s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);tick(100);await s.action();s.releaseAction();tick(200);if(id==='upper'){walk(s,c.floors.upper_1F.routes.entryArrival_stair);await s.action();s.releaseAction();tick(300);walk(s,c.floors.upper_2F.routes.stairArrival_stair);await s.action();s.releaseAction();walk(s,c.floors.upper_1F.routes.stairArrival_entry)}else walk(s,c.floors.family_1F.routes.entryArrival_entry);s.face('down');await s.action();s.releaseAction();tick(400);s.cancel();assert.equal(s.scene,'exterior');assert.equal(e.read().elapsedMs,elapsed);for(const k of ['water','b2','b4','lights'])assert.equal(e.read().options[k],false);assert.equal(e.read().clockOwnerCount,1);s.dispose();globalThis.gc?.()}assert.equal(elapsed,1700)});
test('bad lighting source and invalid environment inputs fail before composition',()=>{assert.throws(()=>createJangmokEnvironment({...A,M:{...A.M,sourceSHA:'0'.repeat(64)}}),/lighting-source-or-authority/);const e=createJangmokEnvironment(A);assert.throws(()=>e.setTime(NaN));assert.throws(()=>e.tick(-1));assert.throws(()=>e.setOption('unknown',true));assert.throws(()=>e.setOption('water',1));assert.equal(e.read().elapsedMs,0)});
